// Opt-in browser check for the real SSR report generated by validate-snapshots.
// Requires Playwright and a locally installed Chromium; makes no HTTP requests.
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const report = process.env.REPORT_HTML_PATH;
const output = process.env.VALIDATION_OUTPUT_DIR;
if (!report || !output) throw new Error('Set REPORT_HTML_PATH and VALIDATION_OUTPUT_DIR.');
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE || 'playwright');
const browser = await chromium.launch({
  headless: true,
  ...(process.env.CHROMIUM_EXECUTABLE ? { executablePath: process.env.CHROMIUM_EXECUTABLE } : {}),
  args: ['--disable-dev-shm-usage'],
});
const results = [];
fs.mkdirSync(output, { recursive: true });
try {
  for (const [name, width, height] of [['phone-small', 360, 800], ['phone', 390, 844], ['tablet', 800, 1280], ['desktop', 1440, 1000]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.goto(pathToFileURL(path.resolve(report)).href);
    for (const open of [false, true]) {
      await page.locator('details').evaluateAll((items, expanded) => items.forEach((element) => { element.open = expanded; }), open);
      const measure = await page.evaluate(() => ({ width: innerWidth, scrollWidth: document.documentElement.scrollWidth, details: document.querySelectorAll('details').length, bodyHeight: document.body.scrollHeight }));
      results.push({ name, open, ...measure });
      if (measure.scrollWidth > width) throw new Error(`Horizontal overflow at ${width}px`);
    }
    await page.screenshot({ path: path.join(output, `${name}.png`), fullPage: true });
    await page.close();
  }
  fs.writeFileSync(path.join(output, 'layout-results.json'), JSON.stringify(results, null, 2) + '\n');
  console.log(`${results.length} report viewport/expansion checks passed. This does not test authenticated routes or PDF downloads.`);
} finally {
  await browser.close();
}
